        const quizModal = document.getElementById('quizModal');
        const quizForm = document.getElementById('quizForm');
        function openAddQuizModal(topicId = '', topicTitle = '') { document.getElementById('quizModalTitle').textContent = topicTitle ? 'Tambah Quiz · ' + topicTitle : 'Tambah Quiz'; quizForm.reset(); quizForm.action = @js(route('quizzes.store')); document.getElementById('quizFormMethod').value = 'POST'; document.getElementById('quizTopic').value = topicId; document.getElementById('quizDuration').value = 1200; document.getElementById('quizPassingGrade').value = 80; quizModal.classList.remove('hidden'); quizModal.classList.add('flex'); document.getElementById('quizTitle').focus(); }
        function openEditQuiz(item) { document.getElementById('quizModalTitle').textContent = 'Edit Quiz'; quizForm.action = '/quizzes/' + item.id; document.getElementById('quizFormMethod').value = 'PUT'; document.getElementById('quizTitle').value = item.title ?? ''; document.getElementById('quizTopic').value = item.topic_id ?? ''; document.getElementById('quizDuration').value = item.duration ?? 0; document.getElementById('quizPassingGrade').value = item.passing_grade ?? 0; quizModal.classList.remove('hidden'); quizModal.classList.add('flex'); document.getElementById('quizTitle').focus(); }
        function closeQuizModal() { quizModal.classList.add('hidden'); quizModal.classList.remove('flex'); }
        document.querySelectorAll('.add-quiz').forEach((button) => button.addEventListener('click', () => openAddQuizModal(button.dataset.topicId, button.dataset.topicTitle)));
        document.querySelectorAll('.edit-quiz').forEach((button) => button.addEventListener('click', () => openEditQuiz(JSON.parse(button.dataset.quiz))));
        document.querySelectorAll('.delete-quiz').forEach((button) => button.addEventListener('click', () => { Swal.fire({ title: 'Hapus quiz?', text: 'Quiz yang sudah memiliki attempt, bobot, atau pertanyaan tidak dapat dihapus.', icon: 'warning', showCancelButton: true, confirmButtonColor: '#dc2626', cancelButtonText: 'Batal', confirmButtonText: 'Ya, hapus' }).then((result) => { if (!result.isConfirmed) return; const form = document.createElement('form'); form.method = 'POST'; form.action = '/quizzes/' + button.dataset.deleteId; form.innerHTML = '@csrf<input type="hidden" name="_method" value="DELETE">'; document.body.appendChild(form); form.submit(); }); }));
        quizModal.addEventListener('click', (event) => { if (event.target === quizModal) closeQuizModal(); });

        const topicModal = document.getElementById('topicModal');
        const topicForm = document.getElementById('topicForm');
        const materialModal = document.getElementById('materialModal');
        const materialVideo = document.getElementById('materialVideo');
        const materialFrame = document.getElementById('materialFrame');
        function openAddTopicModal() { document.getElementById('topicModalTitle').textContent = 'Tambah Topic'; topicForm.reset(); topicForm.action = @js(route('topics.store')); document.getElementById('topicFormMethod').value = 'POST'; document.getElementById('topicOrder').value = 1; topicModal.classList.remove('hidden'); topicModal.classList.add('flex'); document.getElementById('topicTitle').focus(); }
        function openEditTopic(item) { document.getElementById('topicModalTitle').textContent = 'Edit Topic'; topicForm.action = `/topics/${item.id}`; document.getElementById('topicFormMethod').value = 'PUT'; document.getElementById('topicTitle').value = item.title ?? ''; document.getElementById('topicCourse').value = item.course_id ?? ''; document.getElementById('topicOrder').value = item.urutan ?? 1; topicModal.classList.remove('hidden'); topicModal.classList.add('flex'); document.getElementById('topicTitle').focus(); }
        function closeTopicModal() { topicModal.classList.add('hidden'); topicModal.classList.remove('flex'); }
        function openMaterialModal(button) { const url = button.dataset.materialUrl; const type = button.dataset.materialType || 'Materi'; document.getElementById('materialModalTitle').textContent = button.dataset.materialTitle || 'Lesson'; document.getElementById('materialModalType').textContent = type.replaceAll('_', ' '); document.getElementById('materialExternalLink').href = url; const directVideo = /\.(mp4|webm|ogg)(\?.*)?$/i.test(url); materialVideo.classList.toggle('hidden', !directVideo); materialFrame.classList.toggle('hidden', directVideo); if (directVideo) { materialVideo.src = url; materialVideo.load(); } else { materialFrame.src = url; } materialModal.classList.remove('hidden'); materialModal.classList.add('flex'); }
        function closeMaterialModal() { materialVideo.pause(); materialVideo.removeAttribute('src'); materialVideo.load(); materialFrame.src = 'about:blank'; materialModal.classList.add('hidden'); materialModal.classList.remove('flex'); }
        document.querySelectorAll('.edit-topic').forEach((button) => button.addEventListener('click', () => openEditTopic(JSON.parse(button.dataset.topic))));
        document.querySelectorAll('.open-material').forEach((button) => button.addEventListener('click', () => openMaterialModal(button)));
        topicModal.addEventListener('click', (event) => { if (event.target === topicModal) closeTopicModal(); });
        materialModal.addEventListener('click', (event) => { if (event.target === materialModal) closeMaterialModal(); });
        document.addEventListener('keydown', (event) => { if (event.key === 'Escape') { closeQuizModal(); closeTopicModal(); closeMaterialModal(); } });
    </script>
@endsection

